using System.Diagnostics;

namespace N64AssetStudio.Core.Export;

/// <summary>Builds a native .blend by running the user's Blender in background mode. Without Blender,
/// writes .glb files plus a one-click import script.</summary>
public static class BlenderExport
{
    public static string? BlenderPath { get; set; }

    const string Script = """
# Generated by N64 Asset Studio - imports the exported models into Blender.
# Run with:  blender --background --python this_script.py
# or open it in Blender's "Scripting" tab and press "Run Script".
import bpy, os
HERE = r"__FOLDER__"
if not os.path.isdir(HERE):
    HERE = os.path.dirname(os.path.abspath(__file__))
MODELS = [__MODELS__]
OUT = "__OUT__"

bpy.ops.wm.read_factory_settings(use_empty=True)
for rel in MODELS:
    before = set(bpy.data.objects)
    bpy.ops.import_scene.gltf(filepath=os.path.join(HERE, rel))
    new = [o for o in bpy.data.objects if o not in before]
    coll = bpy.data.collections.new(os.path.splitext(os.path.basename(rel))[0])
    bpy.context.scene.collection.children.link(coll)
    for o in new:
        for c in list(o.users_collection):
            c.objects.unlink(o)
        coll.objects.link(o)
for img in bpy.data.images:
    # images from .glb files are already packed; pack anything else
    if img.packed_file is None and img.filepath:
        try:
            img.pack()
        except Exception:
            pass
if OUT:
    bpy.ops.wm.save_as_mainfile(filepath=os.path.join(HERE, OUT))
    print("Saved", OUT)
""";

    public static string? FindBlender()
    {
        if (!string.IsNullOrEmpty(BlenderPath) && File.Exists(BlenderPath)) return BlenderPath;
        var exe = OperatingSystem.IsWindows() ? "blender.exe" : "blender";
        foreach (var dir in (Environment.GetEnvironmentVariable("PATH") ?? "").Split(Path.PathSeparator))
        {
            try { var p = Path.Combine(dir.Trim('"'), exe); if (File.Exists(p)) return p; } catch (ArgumentException) { }
        }
        var hits = new List<string>();
        foreach (var env in new[] { "ProgramFiles", "ProgramFiles(x86)", "LOCALAPPDATA" })
        {
            var root = Environment.GetEnvironmentVariable(env);
            if (string.IsNullOrEmpty(root)) continue;
            var bf = Path.Combine(root, "Blender Foundation");
            if (Directory.Exists(bf))
                foreach (var d in Directory.GetDirectories(bf, "Blender*"))
                    if (File.Exists(Path.Combine(d, "blender.exe"))) hits.Add(Path.Combine(d, "blender.exe"));
            var steam = Path.Combine(root, "Steam", "steamapps", "common", "Blender", "blender.exe");
            if (File.Exists(steam)) hits.Add(steam);
        }
        foreach (var p in new[] { "/Applications/Blender.app/Contents/MacOS/Blender", "/usr/bin/blender", "/snap/bin/blender" })
            if (File.Exists(p)) hits.Add(p);
        return hits.OrderBy(h => h).LastOrDefault();
    }

    public sealed record Result(List<string> Glb, string Script, string? Blend, string Message);

    public static Result Export(IEnumerable<Mesh> meshes, string folder, string blendName, double scale = 1.0)
    {
        Directory.CreateDirectory(folder);
        folder = Path.GetFullPath(folder);
        var rels = new List<string>();
        foreach (var m in meshes)
        {
            string fn = ModelExport.Safe(m.Name) + ".glb";
            ModelExport.Glb(m, Path.Combine(folder, fn), scale);
            rels.Add(fn);
        }
        string blend = ModelExport.Safe(blendName) + ".blend";
        string script = Path.Combine(folder, ModelExport.Safe(blendName) + "_import_into_blender.py");
        File.WriteAllText(script, Script.Replace("__FOLDER__", folder).Replace("__OUT__", blend)
            .Replace("__MODELS__", string.Join(", ", rels.Select(r => $"\"{r}\""))));
        var glbs = rels.Select(r => Path.Combine(folder, r)).ToList();
        var exe = FindBlender();
        if (exe == null)
            return new(glbs, script, null, "Blender was not found, so the .blend could not be built automatically. " +
                $"Open Blender > Scripting, load '{Path.GetFileName(script)}' and press Run Script " +
                "(or set the Blender path in Settings and export again).");
        try
        {
            var psi = new ProcessStartInfo(exe) { CreateNoWindow = true, UseShellExecute = false, WorkingDirectory = folder,
                RedirectStandardOutput = true, RedirectStandardError = true };
            foreach (var a in new[] { "--background", "--factory-startup", "--python", script }) psi.ArgumentList.Add(a);
            using var p = Process.Start(psi)!;
            p.StandardOutput.ReadToEndAsync();
            p.StandardError.ReadToEndAsync();
            if (!p.WaitForExit(900_000)) { p.Kill(true); return new(glbs, script, null, "Blender timed out."); }
            string outPath = Path.Combine(folder, blend);
            return File.Exists(outPath)
                ? new(glbs, script, outPath, $"Created {blend} with Blender ({exe}).")
                : new(glbs, script, null, "Blender ran but did not produce a .blend file.");
        }
        catch (Exception e) { return new(glbs, script, null, $"Blender failed: {e.Message}"); }
    }
}
